const white = '#fff6e7';
const iris = '#ff00ff';
const brow = '#884422';
const lip = '#cc5577';

const eye = (id, es, en, family, size, body) => ({ id, kind: 'eye', es, en, family, size, width: 96, height: 64, body, tintSlots: { [iris]: 'iris' } });
const eyebrow = (id, es, en, family, size, body) => ({ id, kind: 'brow', es, en, family, size, width: 96, height: 32, body, tintSlots: { [brow]: 'brow' } });
const mouth = (id, es, en, family, size, body) => ({ id, kind: 'mouth', es, en, family, size, width: 96, height: 40, body, tintSlots: { [lip]: 'lip' } });

