export function forgeSpriteId(art) {
  return art.id.replace(/^forge_([a-z]+)_/, '$1_forge_');
}

export function forgeArtSvg(art) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${art.width}" height="${art.height}" viewBox="0 0 ${art.width} ${art.height}">${art.body}</svg>`;
}

function editableMarkup(art) {
  let body = art.body.replaceAll(iris, '{{iris}}').replaceAll(brow, '{{hairDark}}').replaceAll(lip, '{{lip}}');
  const group = (suffix, transform) => `<g id="FORGE_${art.kind.toUpperCase()}_${suffix}" data-rv-role="${art.kind === 'eye' ? 'eye_white' : art.kind}" transform="${transform}">${body}</g>`;
  if (art.kind === 'mouth') return group('CENTER', 'translate(222 309) scale(0.7 0.5)');
  const y = art.kind === 'eye' ? 230 : 204;
  const scaleY = art.kind === 'eye' ? 0.54 : 0.44;
  return group('L', `translate(184 ${y}) scale(0.58 ${scaleY})`) + group('R', `translate(328 ${y}) scale(-0.58 ${scaleY})`);
}

export function forgeFeaturePresets(kind) {
  return FORGE_FACE_ART.filter(art => art.kind === kind).map(art => Object.freeze({
    id: art.id, spriteId: forgeSpriteId(art), label: art.en,
    labels: Object.freeze({ es: art.es, en: art.en }),
    family: art.family, type: { eye: 'eyes', brow: 'brows', mouth: 'mouth' }[kind], buildMode: 'mold',
    mountRole: { eye: 'eyePair', brow: 'browPair', mouth: 'mouth' }[kind],
    placementDefaults: Object.freeze({ size: art.size, offsetX: 0, offsetY: 0 }),
    silhouetteGoal: art.en, compatibilityNotes: 'Original vector feature fitted to generated head landmarks.',
    rolloutPass: 'forge-face-refresh', validationStatus: 'validated',
    validationEvidence: 'artifacts/avatar-forge-refresh/original-faces-{front,three-quarter,profile}.png',
    markup: editableMarkup(art),
  }));
}
